output_text:
[
  {
    "id": "no_carts_single_file",
    "text": "Shopping carts are prohibited in single-file shelf aisles, i.e. shelf-adjacent cells whose horizontal free width is only one cell.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "singleFileShelfAisle",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "no_enter_single_file_with_cart",
    "text": "An agent must not move into a single-file shelf aisle while still holding the cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "enterSingleFileWithCart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": {
            "and": [
              "hasCart",
              "singleFileShelfAisle"
            ]
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileWithCart"
    }
  },
  {
    "id": "no_push_north_from_item_mouth",
    "text": "At the mouth of a narrow north-going item aisle, the agent must not push the cart north into the aisle.",
    "abstraction": {
      "state_properties": {
        "narrowItemAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "narrowItemAisleMouth",
          "hasCart",
          "N"
        ]
      }
    }
  },
  {
    "id": "retrieve_after_cartless_single_file_pick",
    "text": "After picking an item while cartless in a single-file shelf aisle, the agent is obliged to retrieve a cart before exiting.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "narrowItemAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "cartlessSingleFilePick": {
          "pre": {
            "and": [
              "singleFileShelfAisle",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": null
        },
        "retrieveCartAtMouth": {
          "pre": {
            "and": [
              "narrowItemAisleMouth",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cartlessSingleFilePick",
      "discharge": "retrieveCartAtMouth"
    }
  },
  {
    "id": "cart_required_open_shelf_pick",
    "text": "Shelf interactions in open or two-wide shopping areas require having the cart; only single-file aisle picks may be done without it.",
    "abstraction": {
      "state_properties": {
        "openShelfPosition": {
          "and": [
            "adjShelf",
            {
              "gt": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "openShelfPosition",
          "INTERACT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "park_only_at_narrow_mouths",
    "text": "Dropping or parking the cart is permitted only at the wide aisle mouths outside the narrow item aisles.",
    "abstraction": {
      "state_properties": {
        "narrowItemAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "dropCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "dropCart",
          {
            "not": "narrowItemAisleMouth"
          }
        ]
      }
    }
  },
  {
    "id": "retrieve_after_parking_at_mouth",
    "text": "Whenever the cart is parked at a narrow-aisle mouth, it must later be retrieved from a narrow-aisle mouth before the trip ends.",
    "abstraction": {
      "state_properties": {
        "narrowItemAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "parkCartAtMouth": {
          "pre": {
            "and": [
              "narrowItemAisleMouth",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "retrieveCartAtMouth": {
          "pre": {
            "and": [
              "narrowItemAisleMouth",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "parkCartAtMouth",
      "discharge": "retrieveCartAtMouth"
    }
  },
  {
    "id": "no_leave_mouth_without_cart",
    "text": "After parking the cart at a narrow-aisle mouth, the agent may go north into the aisle without it, but must not leave the mouth in any other direction without retrieving the cart.",
    "abstraction": {
      "state_properties": {
        "narrowItemAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "leavingMouthSidewaysOrBack": {
          "or": [
            "S",
            "E",
            "W"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "narrowItemAisleMouth",
          {
            "not": "hasCart"
          },
          "leavingMouthSidewaysOrBack"
        ]
      }
    }
  }
]
